const slotOwners = `-- name: SlotOwners :many
SELECT s.name AS slot_name, u.id AS user_id FROM slots s JOIN users u ON u.slot_id = s.id
WHERE s.name = ANY($1::text[])
UNION
SELECT s.name AS slot_name, d.user_id AS user_id FROM slots s JOIN bound_devices d ON d.slot_id = s.id
WHERE s.name = ANY($1::text[])
`

type SlotOwnersRow struct {
	SlotName string
	UserID   int64
}

// The users of the named slots: the own slot and those of bound devices.
func (q *Queries) SlotOwners(ctx context.Context, names []string) ([]SlotOwnersRow, error) {
	rows, err := q.db.QueryContext(ctx, slotOwners, pq.Array(names))
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SlotOwnersRow{}
	for rows.Next() {
		var i SlotOwnersRow
		if err := rows.Scan(&i.SlotName, &i.UserID); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

