const upsertDevices = `-- name: UpsertDevices :exec
INSERT INTO devices (user_id, ip, first_seen, last_seen)
SELECT t.user_id, t.ip, $1::bigint, $1::bigint
FROM (SELECT unnest($2::bigint[]) AS user_id, unnest($3::text[]) AS ip) AS t
JOIN users u ON u.id = t.user_id
ORDER BY t.user_id, t.ip
ON CONFLICT (user_id, ip) DO UPDATE SET last_seen = excluded.last_seen
`

type UpsertDevicesParams struct {
	Now     int64
	UserIds []int64
	Ips     []string
}

// Devices seen online. A user deleted meanwhile is skipped: the rest still goes in.
func (q *Queries) UpsertDevices(ctx context.Context, arg UpsertDevicesParams) error {
	_, err := q.db.ExecContext(ctx, upsertDevices, arg.Now, pq.Array(arg.UserIds), pq.Array(arg.Ips))
	return err
}

